// src/probe-workspace.ts
import { copyFile, mkdir, mkdtemp, rm } from "node:fs/promises";
import { join as join3 } from "node:path";
import { tmpdir } from "node:os";
var AGENT_SKILL_ROOTS = {
  claude: [".claude", "skills"],
  gemini: [".gemini", "skills"],
  codex: [".agents", "skills"]
};
function safeSkillName(name) {
  return name.replace(/[^A-Za-z0-9._-]/g, "-").replace(/^\.+/, "") || "skill";
}
async function createProbeWorkspace(agent, skillFilePath, skillName) {
  const rootParts = AGENT_SKILL_ROOTS[agent];
  if (!rootParts) {
    throw new Error(`Cannot stage skill for unknown agent "${agent}"`);
  }
  const cwd = await mkdtemp(join3(tmpdir(), "tripwire-probe-"));
  const skillDir = join3(cwd, ...rootParts, safeSkillName(skillName));
  const skillPath = join3(skillDir, "SKILL.md");
  await mkdir(skillDir, { recursive: true });
  await copyFile(skillFilePath, skillPath);
  return {
    cwd,
    skillPath,
    cleanup: () => rm(cwd, { recursive: true, force: true })
  };
}

// src/action/probe.ts
async function probeSkill(input2) {
  const workspace = await createProbeWorkspace("claude", input2.skillFilePath, input2.skillName);
  try {
    const factory = input2.adapterFactory ?? ((name, cwd) => new ClaudeCodeAdapter(name, { cwd }));
    const adapter = factory(input2.skillName, workspace.cwd);
    const results = await runScenariosFromFile(input2.scenariosPath, adapter, () => {
    });
    const regressions = classifyRegressions(results);
    return { skillName: input2.skillName, results, regressions };
  } finally {
    await workspace.cleanup();
  }
}
function classifyRegressions(results) {
  const out = [];
  for (const r of results) {
    if (r.transcript.error) {
      out.push({
        prompt: r.prompt.prompt,
        zone: r.prompt.zone,
        kind: "infrastructure",
        error: r.transcript.error
      });
      continue;
    }
    const expected = expectedActivationFor(r.prompt);
    const activated = r.transcript.activated;
    if (expected && !activated) {
      out.push({ prompt: r.prompt.prompt, zone: r.prompt.zone, kind: "gap" });
    } else if (!expected && activated) {
      out.push({ prompt: r.prompt.prompt, zone: r.prompt.zone, kind: "false-positive" });
    }
  }
  return out;
}

// src/action/comment.ts
var MARKER = "<!-- tripwire -->";
var API = "https://api.github.com";
function headers(token) {
  return {
    Authorization: `Bearer ${token}`,
    Accept: "application/vnd.github+json",
    "Content-Type": "application/json",
    "User-Agent": "tripwire-action"
  };
}
async function upsertStickyComment(opts) {
  const fetchImpl = opts.fetchImpl ?? fetch;
  const body = opts.body.includes(MARKER) ? opts.body : `${opts.body}

${MARKER}`;
  try {
    let marked;
    let page = 1;
    while (!marked) {
      const listRes = await fetchImpl(
        `${API}/repos/${opts.repo}/issues/${opts.prNumber}/comments?per_page=100&page=${page}`,
        { method: "GET", headers: headers(opts.token) }
      );
      if (!listRes.ok) break;
      const comments = await listRes.json();
      marked = comments.find((c3) => (c3.body ?? "").includes(MARKER));
      if (comments.length < 100) break;
      page++;
    }
    if (marked) {
      const res2 = await fetchImpl(`${API}/repos/${opts.repo}/issues/comments/${marked.id}`, {
        method: "PATCH",
        headers: headers(opts.token),
        body: JSON.stringify({ body })
      });
      return res2.ok ? "updated" : "skipped";
    }
    const res = await fetchImpl(`${API}/repos/${opts.repo}/issues/${opts.prNumber}/comments`, {
      method: "POST",
      headers: headers(opts.token),
      body: JSON.stringify({ body })
    });
    return res.ok ? "created" : "skipped";
  } catch {
    return "skipped";
  }
}

// src/action/report.ts
function renderComment(reports) {
  const lines = ["## \u{1FAA4} Tripwire", ""];
  const totalErrors = reports.reduce((n2, r) => n2 + r.lint.errors.length, 0);
  const totalWarnings = reports.reduce((n2, r) => n2 + r.lint.warnings.length, 0);
  const totalRegressions = reports.reduce((n2, r) => n2 + (r.probe?.regressions.length ?? 0), 0);
  if (totalErrors === 0 && totalWarnings === 0 && totalRegressions === 0) {
    lines.push("\u2705 All changed skills passed \u2014 no issues found.");
  } else {
    lines.push(
      `Found ${totalErrors} error(s), ${totalWarnings} warning(s), ${totalRegressions} coverage regression(s) across ${reports.length} skill(s).`
    );
  }
  lines.push("");
  for (const r of reports) {
    lines.push(`### \`${r.file}\``);
    if (r.lint.errors.length === 0 && r.lint.warnings.length === 0) {
      lines.push("- \u2705 lint clean");
    } else {
      for (const e of r.lint.errors) lines.push(`- \u274C **${e.rule}** \u2014 ${e.message}`);
      for (const w of r.lint.warnings) lines.push(`- \u26A0\uFE0F **${w.rule}** \u2014 ${w.message}`);
    }
    if (r.probeSkipped) {
      lines.push(`- \u2139\uFE0F coverage probe skipped: ${r.probeSkipped}`);
    } else if (r.probe) {
      if (r.probe.regressions.length === 0) {
        lines.push(`- \u2705 coverage: ${r.probe.results.length} scenario(s), no regressions`);
      } else {
        for (const reg of r.probe.regressions) {
          const label = reg.kind === "gap" ? "gap (did not activate)" : reg.kind === "false-positive" ? "false positive (activated)" : `infrastructure error${reg.error ? ` (${reg.error})` : ""}`;
          lines.push(`- \u274C coverage ${label} [${reg.zone}]: "${reg.prompt}"`);
        }
      }
    }
    lines.push("");
  }
  lines.push(MARKER);
  return lines.join("\n");
}
function computeExitCode(reports, failOnWarning) {
  for (const r of reports) {
    if (r.lint.errors.length > 0) return 1;
    if (failOnWarning && r.lint.warnings.length > 0) return 1;
    if (r.probe && r.probe.regressions.length > 0) return 1;
  }
  return 0;
}

// src/action/context.ts
function readContext(env, readEventFile) {
  const eventPath = env.GITHUB_EVENT_PATH;
  let base = env.GITHUB_BASE_REF || "";
  let head = env.GITHUB_HEAD_REF || env.GITHUB_SHA || "HEAD";
  let prNumber = null;
  if (eventPath) {
    try {
      const event = JSON.parse(readEventFile(eventPath));
      if (event.pull_request) {
        base = event.pull_request.base?.sha || base;
        head = event.pull_request.head?.sha || head;
        prNumber = event.pull_request.number ?? null;
      } else if (event.before && event.after) {
        base = event.before;
        head = event.after;
      }
    } catch {
    }
  }
  return {
    base,
    head,
    repo: env.GITHUB_REPOSITORY || "",
    prNumber,
    token: env.GITHUB_TOKEN || ""
  };
}

